async function profile(id:string){const r=row(id)!;const awards=records('award').filter(v=>v.data.scholar_id===id);modal(r.data.name,`<p>${esc(r.data.research_summary||'Summary not provided.')}</p><dl class="detail-list"><dt>Institution / unit</dt><dd>${esc(name(r.data.institution_id))}<br>${esc(name(r.data.unit_id))}</dd><dt>Contact</dt><dd>${esc(r.data.email)}</dd><dt>Academic stage</dt><dd>${esc(r.data.stage)}</dd></dl><h3>Award-year records</h3>${awards.map(v=>`<div class="row"><div class="row-main"><h3>${esc(v.data.academic_year)}</h3><p>Synthetic preexisting record · ${amount(v.data.minor_units,v.data.currency)}</p></div></div>`).join('')||'<p>No award records shared.</p>'}<h3 class="section-space">Purpose-specific consent</h3>${records('consent').filter(v=>v.data.scholar_id===id).map(v=>`<div class="row"><div class="row-main">${esc(label(v.data.purpose))}</div>${badge(v.data.status,v.data.status==='revoked'?'bad':'neutral')}${btn('Edit','consent','ghost',`data-id="${v.id}"`)}</div>`).join('')||'<p>No consent records provided.</p>'}<div class="section-space actions">${btn('Edit profile','edit-scholar','',`data-id="${id}"`)}${btn('Add permission','new-consent','secondary',`data-scholar="${id}"`)}${btn('Draft update request','contact','secondary',`data-id="${id}"`)}</div>`);}
function parseCSV(text:string){const rows:string[][]=[];let current:string[]=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){current.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;current.push(value);if(current.some(x=>x.trim()))rows.push(current);current=[];value='';}else value+=c;}if(quoted)throw new Error('Unclosed CSV quotation.');current.push(value);if(current.some(x=>x.trim()))rows.push(current);const headers=rows.shift()||[];return rows.map(r=>{if(r.length!==headers.length)throw new Error('CSV column count differs from header.');return Object.fromEntries(headers.map((h,i)=>[h.trim(),r[i].trim()]));});}
function rosterImport(){const csv='name,email,institution_id,unit_id,stage,academic_year,research_summary\nDemo Scholar Aster,scholar-aster@scholars.example,caltech,unit-caltech,PhD,2025–2026,Synthetic duplicate candidate\nDemo Scholar Delta,delta@scholars.example,usc,unit-keck,MD,2025–2026,Synthetic research summary';modal('Import a synthetic roster',`<div class="notice">Only fictional people and .example email addresses. Existing candidates require linking or skipping; no automatic merge or award authorization.</div><label class="field"><span>Choose CSV file (optional)</span><input id="csv-file" type="file" accept=".csv,text/csv"></label>${field('Roster CSV','csv',csv,'textarea','Institution/unit IDs must match the hierarchy above. Every row is validated.')}`,'Validate and propose diff',async fd=>{const out=await api('/roster-imports',{rows:parseCSV(String(fd.get('csv')))});close();await refresh();rosterReview(out.id);});}
function rosterReview(id:string){const imp=row(id)!;modal('Review proposed roster diff',`<div class="notice">Explicitly decide each row. Linking records only records reconciliation; it does not merge or overwrite a person or authorize an award.</div>${imp.data.rows.map((item:any)=>`<div class="scene-editor"><h3>${esc(item.row.name)}</h3><p>${esc(item.row.email)} · ${esc(name(item.row.unit_id))}</p>${item.candidate_ids.length||item.duplicate_in_upload?badge('duplicate_candidate','warn'):badge('proposed_new_profile')}<details><summary>Inspect imported fields and candidates</summary><div class="pre">${esc(pretty(item))}</div></details>${select('Reconciliation decision','decision-'+item.index,item.candidate_ids.length?['skip',...item.candidate_ids.map((id:string)=>({id:'link:'+id,title:'Link to '+name(id)}))]:item.duplicate_in_upload?['skip']:['create','skip'],item.candidate_ids.length?'skip':'create')}</div>`).join('')}`,'Propose exact reconciliation for approval',async fd=>{const decisions=imp.data.rows.map((item:any)=>{const v=String(fd.get('decision-'+item.index));return v.startsWith('link:')?{index:item.index,decision:'link',scholar_id:v.slice(5)}:{index:item.index,decision:v};});await api('/approvals',{action:'roster_reconcile',targets:[id],payload:{import_id:id,decisions}});close();location.hash='#/approvals';await refresh();toast('Reconciliation proposed. Switch to an independent authorized approver.');});}
function communication(type:'profile_update'|'invitation',id:string){const r=row(id)!;modal(type==='profile_update'?'Draft profile-update request':'Draft event invitation',`<div class="notice">Exact-recipient preview. No message will be sent; this creates a version-bound approval for simulation.</div>${field('Recipient (.example only)','recipient',type==='profile_update'?r.data.email:'guest@invitees.example','email')}${field('Subject','subject',type==='profile_update'?'Synthetic profile update request':'Synthetic invitation: '+r.data.title)}${field('Draft message','body',type==='profile_update'?'Please review the synthetic research profile and share any corrections. This is a local demonstration and has not been sent.':'We are preparing a fictional chapter conversation. This invitation is a draft for human review; no actual event invitation will be delivered.','textarea')}${select('Simulation outcome','simulation',['success','failure','unknown'],'success')}`,'Propose for independent approval',async fd=>{const payload:any={recipient:String(fd.get('recipient')),subject:String(fd.get('subject')),body:String(fd.get('body')),simulation:String(fd.get('simulation'))};payload[type==='profile_update'?'scholar_id':'event_id']=id;await api('/approvals',{action:type,targets:[id],payload});close();location.hash='#/approvals';await refresh();toast('Draft proposed; nothing was sent.');});}
async function approvalDetail(id:string){const r=await api('/approvals/'+id);const expired=r.expires_at<new Date().toISOString();modal('Inspect exact approval',`<div class="badges">${badge(r.action_type,'blue')}${badge(expired&&r.status==='pending_review'?'expired':r.status,'warn')}</div>${r.payload.recipient?`<h3>Recipient: ${esc(r.payload.recipient)}</h3><p>${esc(r.payload.subject)}</p><div class="pre">${esc(r.payload.body)}</div>`:''}<dl class="detail-list"><dt>Proposer / approver</dt><dd>${esc(r.proposer)} / ${esc(r.approver||'Not yet approved')}</dd><dt>Targets</dt><dd>${r.targets.map((v:string)=>esc(name(v))).join('<br>')}</dd><dt>Expiration</dt><dd>${esc(r.expires_at)}</dd><dt>Policy version</dt><dd>${esc(r.policy_version)}</dd><dt>Canonical payload hash</dt><dd class="pre">${esc(r.payload_hash)}</dd></dl><details open><summary>Exact payload and target revisions</summary><div class="pre">${esc(pretty({payload:r.payload,dependencies:r.dependencies}))}</div></details><div class="notice">External writes remain mocked, even after approval. A simulated unknown outcome must be reconciled; the same approval cannot be resent.</div><div class="actions">${r.status==='pending_review'&&!expired?`${btn('Approve exact payload','decide-approve','',`data-id="${id}" data-hash="${r.payload_hash}"`)}${btn('Reject','decide-reject','warning',`data-id="${id}" data-hash="${r.payload_hash}"`)}`:''}${r.status==='approved'?btn('Simulate approved action','execute','',`data-id="${id}" data-hash="${r.payload_hash}"`):''}${r.status==='outcome_unknown'?badge('manual_reconciliation_required','bad')+btn('Record simulated reconciliation','reconcile','secondary',`data-id="${id}"`):''}</div><div id="form-error"></div>`);}
function agentDialog(role='Coordinator',context?:string[]){modal('Request an agent draft',`${select('Agent role','role',state.agent_roles,role)}${field('Human-requested objective','objective',role==='Story Producer'?'Prepare a source-grounded treatment, interview guide, and review checklist for this synthetic scholar story.':'Prepare a chapter operations draft using the selected evidence only.','textarea')}<h3>Authorized context</h3><p class="note">Only selected accessible records enter this local mock adapter. Retrieved text cannot change permissions or approval requirements.</p><div class="pre">${state.records.filter((r:Row)=>['source','film','scholar','event','decision','script','film_claim'].includes(r.kind)).map((r:Row)=>`<label class="check"><input type="checkbox" name="context" value="${r.id}" ${context?.includes(r.id)?'checked':''}><span>${esc(r.data.title||r.data.name||r.data.wording||r.kind)} <small>(${esc(r.id)})</small></span></label>`).join('')}</div>`,'Queue mock draft job',async fd=>{await api('/agent-runs',{role:String(fd.get('role')),objective:String(fd.get('objective')),context:fd.getAll('context').map(String)});close();location.hash='#/agents';await refresh();toast('Job saved. Run it explicitly from the durable queue.');});}
function editScript(){const current:Row=film.records.filter((r:Row)=>r.kind==='script').sort((a:Row,b:Row)=>b.data.version-a.data.version)[0];const scenes=current?.data.scenes||[{id:'scene-1',order:1,purpose:'Introduce the question',duration:30,audio:'Proposed narration for a synthetic story.',audio_type:'proposed_narration',visual:'Illustrative diagram',visual_class:'illustrative_animation',claim_ids:[],quote_ids:[],asset_ids:[],notes:'Draft only',status:'draft'}];modal('Save a new script version',`<p class="note">The previous version remains intact. New material invalidates dependent final-cut reviews. Runtime is the sum of proposed scene durations.</p>${scenes.map((v:any,i:number)=>`<div class="scene-editor"><h3>${esc(v.id)} · Scene ${i+1}</h3>${field('Narrative purpose','purpose-'+i,v.purpose)}${field('Proposed duration in seconds','duration-'+i,v.duration,'number')}${select('Audio type','audio_type-'+i,['proposed_narration','paraphrase','verbatim'],v.audio_type)}${field('Audio text','audio-'+i,v.audio,'textarea')}${field('Proposed visuals','visual-'+i,v.visual,'textarea')}${select('Visual classification','visual_class-'+i,['documentary_footage','scientific_visualization','illustrative_animation','ai_generated_illustration'],v.visual_class)}${field('Claim references, comma separated (optional)','claim_ids-'+i,v.claim_ids.join(', ')).replace(' required','')}${field('Quote references, comma separated (optional)','quote_ids-'+i,v.quote_ids.join(', ')).replace(' required','')}${field('Asset references, comma separated (optional)','asset_ids-'+i,v.asset_ids.join(', ')).replace(' required','')}${field('Review notes','notes-'+i,v.notes||'Draft for review','textarea')}</div>`).join('')}`,'Save next script version',async fd=>{const next=scenes.map((v:any,i:number)=>({...v,purpose:String(fd.get('purpose-'+i)),duration:Number(fd.get('duration-'+i)),audio:String(fd.get('audio-'+i)),audio_type:String(fd.get('audio_type-'+i)),visual:String(fd.get('visual-'+i)),visual_class:String(fd.get('visual_class-'+i)),claim_ids:String(fd.get('claim_ids-'+i)||'').split(',').map(x=>x.trim()).filter(Boolean),quote_ids:String(fd.get('quote_ids-'+i)||'').split(',').map(x=>x.trim()).filter(Boolean),asset_ids:String(fd.get('asset_ids-'+i)||'').split(',').map(x=>x.trim()).filter(Boolean),notes:String(fd.get('notes-'+i)),status:'draft'}));await saved('script',{film_id:filmId,title:'Script draft',version:(current?.data.version||0)+1,scenes:next});});}
function transcriptDialog(){modal('Import authorized transcript notes',`<div class="notice">Use synthetic text in this demo. Import authorization and participant permission are distinct from permission to publish. No account is connected.</div>${field('Interview title','title','Synthetic interview notes')}${field('Authorization reference','authorization_ref','Synthetic demo participant authorization')}${field('Interview date','date','2026-11-01','date')}${field('Speaker label','speaker','Demo Scholar Aster (fictional)')}${field('Transcript segment / manually entered notes','text','In this fictional example, we want to understand where the uncertainty comes from.','textarea')}<p class="note">Timecodes are not supplied by this form and will remain null. No recordings are uploaded.</p>`,'Save private transcript',async fd=>{const version=1+Math.max(0,...film.records.filter((r:Row)=>r.kind==='interview').map((r:Row)=>r.data.version));const interview=await api('/records',{kind:'interview',data:{film_id:filmId,title:String(fd.get('title')),participants:film.film.data.scholar_ids,recording_ref:null,authorization_ref:String(fd.get('authorization_ref')),date:String(fd.get('date')),version,follow_up:'Confirm context, uncertainty, and team contributions.'}});await api('/records',{kind:'segment',data:{film_id:filmId,interview_id:interview.id,speaker:String(fd.get('speaker')),text:String(fd.get('text')),start_ms:null,end_ms:null}});close();await refresh();toast('Private transcript saved; publication not authorized.');});}
function rightsDialog(id:string){const asset:Row=film.records.find((r:Row)=>r.id===id),right:Row|undefined=film.records.find((r:Row)=>r.kind==='asset_right'&&r.data.asset_id===id);modal('Asset rights record',`<h3>${esc(asset.data.title)}</h3>${field('Rights basis / authorization reference','basis',right?.data.basis||'Synthetic authorized permission record')}${select('Clearance state','status',['pending','cleared','revoked'],right?.data.status||'pending')}${field('Permitted uses, comma separated','uses',right?.data.uses.join(', ')||film.film.data.uses.join(', '))}${field('Restrictions','restrictions',right?.data.restrictions||'Synthetic demonstration only; confirm actual license before production.','textarea')}<p class="note">A prototype checkbox does not replace a valid license or institutional permission.</p>`,'Save rights assessment',async fd=>saved('asset_right',{film_id:filmId,asset_id:id,basis:String(fd.get('basis')),uses:String(fd.get('uses')).split(',').map(x=>x.trim()).filter(Boolean),restrictions:String(fd.get('restrictions')),status:String(fd.get('status'))},right?.id));}
function cutDialog(){const version=1+Math.max(0,...film.records.filter((r:Row)=>r.kind==='cut').map((r:Row)=>r.data.version));modal('Register a new cut version',`<div class="notice">Register a reference and a known SHA-256. The app does not render video or verify the referenced file’s bytes. New cuts require renewed reviews.</div>${field('Cut title','title','Manual cut v'+version)}${field('Authorized reference (manual:identifier)','reference','manual:cut-v'+version)}${field('Exact artifact SHA-256 (64 lowercase hex characters)','sha256','')}${field('Final captions / caption reference','captions','Prepared caption reference pending human review','textarea')}${field('Final transcript','transcript','Synthetic final transcript for review.','textarea')}${field('Credits','credits','Demo production team; rights must be cleared.','textarea')}`,'Register next cut version',async fd=>saved('cut',{film_id:filmId,title:String(fd.get('title')),version,reference:String(fd.get('reference')),sha256:String(fd.get('sha256')),captions:String(fd.get('captions')),transcript:String(fd.get('transcript')),credits:String(fd.get('credits')),preview_path:null,poster_path:null}));}
function filmReview(gate:string){modal('Review '+label(gate),`<div class="notice">You must be the designated reviewer or authorized chapter approver for this gate, and cannot be the production owner.</div><dl class="detail-list"><dt>Exact cut</dt><dd>${esc(film.state.cut_id)}</dd><dt>Material snapshot</dt><dd class="pre">${esc(film.state.snapshot)}</dd></dl>${select('Review decision','decision',['approved','changes_requested'],'approved')}${field('Assessment and supporting authorization reference','notes','Reviewed synthetic materials for this specific gate.','textarea')}`,'Record version-bound review',async fd=>{await api('/films/'+filmId+'/reviews',{gate,decision:String(fd.get('decision')),notes:String(fd.get('notes')),snapshot:film.state.snapshot,cut_id:film.state.cut_id});close();await refresh();toast('Review recorded for this exact cut and snapshot.');});}
function claimReview(id:string){const claim:Row=film.records.find((r:Row)=>r.id===id);modal('Scientific claim review',`<h3>${esc(claim.data.wording)}</h3><p>${esc(claim.data.evidence_scope)}</p><p>Limitations: ${esc(claim.data.limitations)}</p>${select('Reviewer decision','decision',['approved','changes_requested'])}${field('Scientific review notes','notes','Reviewed synthetic claim scope and limitations.','textarea')}`,'Record scientific decision',async fd=>{await api('/films/'+filmId+'/claims/'+id+'/review',{revision:claim.revision,decision:String(fd.get('decision')),notes:String(fd.get('notes'))});close();await refresh();toast('Scientific review saved; final-cut gate remains separate.');});}
async function briefing(){const out=await api('/briefing?year='+encodeURIComponent(state.metrics.period.academic_year)+'&start='+state.metrics.period.start+'&end='+state.metrics.period.end);modal(out.title,`<div class="notice">Draft briefing · synthetic records · ${esc(out.period.start)} to ${esc(out.period.end)}. This is not an official impact statement.</div><h3>Period-derived metrics</h3><p>${out.metrics.unique_scholars} unique scholars · ${out.metrics.award_records} award records · ${out.metrics.overdue_tasks} overdue tasks</p><h3>Sources and periods</h3>${out.sources.map((v:any)=>`<div class="row"><div class="row-main"><h3>${esc(v.title)}</h3><p>${esc(v.period)} · ${esc(v.state)}</p></div></div>`).join('')}<h3 class="section-space">Handover tasks and decisions</h3>${taskRows(out.tasks)}<h3 class="section-space">Unresolved issues</h3><ul>${out.unresolved.map((v:string)=>`<li class="note">${esc(v)}</li>`).join('')}</ul><div class="actions">${btn('Download briefing JSON','download-briefing','')}</div>`);($('#modal').querySelector('[data-action="download-briefing"]') as HTMLElement).addEventListener('click',()=>download(pretty(out),'arcs-draft-chapter-briefing.json','application/json'));}
async function act(action:string,el:HTMLElement){const id=el.dataset.id||'';
 if(action==='close'){close();return;}
 if(action==='menu'){$('.sidebar').classList.toggle('open');return;}
 if(action==='login'){await api('/demo-session',{identity:id});close();await refresh();return;}
 if(action==='switch'){modal('Switch synthetic identity',`<p class="note">Explicit demonstration mode only. Roles are assigned server-side; the browser cannot submit a custom role or organization. Switching identities does not change record assignments.</p><div class="identity-grid">${meta.identities.map((p:any)=>`<button class="identity-choice" data-action="login" data-id="${p.id}">${esc(p.name)}<small>${esc(label(p.role))}</small></button>`).join('')}</div>`);return;}
 const mapped:Record<string,string>={'new-scholar':'scholar','edit-scholar':'scholar','new-event':'event','edit-event':'event','new-task':'task','new-gift':'gift','new-donor':'donor','new-campaign':'campaign','new-film':'film','edit-film':'film','new-shot':'shot','edit-shot':'shot','new-film-claim':'film_claim','edit-film-claim':'film_claim','new-asset':'asset','new-consent':'consent','consent':'consent'};
 if(mapped[action]){recordForm(mapped[action],action.startsWith('edit-')||action==='consent'?id:undefined,{...(el.dataset.film?{film_id:el.dataset.film}:{}),...(el.dataset.event?{event_id:el.dataset.event}:{}),...(el.dataset.scope?{scope:el.dataset.scope}:{}),...(el.dataset.scholar?{scholar_id:el.dataset.scholar}:{})});return;}
 if(action==='profile'){await profile(id);return;}
 if(action==='contact'||action==='invite'){communication(action==='contact'?'profile_update':'invitation',id);return;}
 if(action==='import'){rosterImport();return;}
 if(action==='roster-review'){rosterReview(id);return;}
 if(action==='task-done'){const r=row(id)!;await api('/records/'+id,{revision:r.revision,data:{...r.data,status:'done'}},'PUT');await refresh();toast('Task completed locally.');return;}
 if(action==='approval-detail'){await approvalDetail(id);return;}
 if(action==='decide-approve'||action==='decide-reject'){await api('/approvals/'+id+'/decision',{decision:action==='decide-approve'?'approved':'rejected',payload_hash:el.dataset.hash});close();await refresh();await approvalDetail(id);return;}
 if(action==='reconcile'){modal('Reconcile simulated unknown outcome',select('Recorded outcome','outcome',['confirmed_failed','confirmed_succeeded'])+field('Human verification / reconciliation reference','reference','Reviewed synthetic provider record; no actual delivery occurred.','textarea'),'Record reconciliation',async fd=>{await api('/approvals/'+id+'/reconcile',{outcome:String(fd.get('outcome')),reference:String(fd.get('reference'))});close();await refresh();toast('Reconciliation recorded. The old approval remains consumed.');});return;}
 if(action==='execute'){const result=await api('/approvals/'+id+'/execute',{payload_hash:el.dataset.hash,idempotency_key:crypto.randomUUID()});close();await refresh();toast(result.message);return;}
 if(action==='new-agent'){agentDialog(el.dataset.role||'Coordinator');return;}
 if(action==='story-agent'){agentDialog('Story Producer',[id,'source-research-demo']);return;}
 if(action==='run-agent'){await api('/agent-runs/'+id+'/run',{});await refresh();toast('Mock draft created; no model service contacted.');return;}
 if(action==='film-tab'){filmTab=el.dataset.tab!;location.hash='#/studio/'+filmId+'/'+filmTab;render();return;}
 if(action==='edit-script'){editScript();return;}
 if(action==='transcript'){transcriptDialog();return;}
 if(action==='quote'){const seg:Row=film.records.find((r:Row)=>r.id===id);modal('Select an exact quotation',`<p>Speaker: ${esc(seg.data.speaker)}</p><div class="pre">${esc(seg.data.text)}</div>${field('Exact excerpt from this segment','text',seg.data.text,'textarea')}`,'Save source-linked quote',async fd=>saved('quote',{film_id:filmId,segment_id:id,text:String(fd.get('text')),type:'verbatim'}));return;}
 if(action==='claim-review'){claimReview(id);return;}
 if(action==='rights'){rightsDialog(id);return;}
 if(action==='new-cut'){cutDialog();return;}
 if(action==='film-review'){filmReview(el.dataset.gate!);return;}
 if(action==='release-ready'){const out=await api('/films/'+id+'/release-ready',{});await refresh();toast(out.published?'Unexpected publication state':'Release-ready recorded. Nothing published.');return;}
 if(action==='release-package'){await api('/films/'+id+'/release-package',{});filmTab='exports';location.hash='#/studio/'+id+'/exports';await refresh();toast('Draft release package saved; blockers retained.');return;}
 if(action==='distribution'){modal('Propose mock distribution',`<div class="notice">All release gates must pass for the exact current cut and intended destinations. This is a simulated action only.</div><p>Destinations: ${esc(film.film.data.uses.join(', '))}</p>${select('Simulation outcome','simulation',['success','failure','unknown'])}`,'Propose exact mock action',async fd=>{await api('/approvals',{action:'film_release',targets:[id],payload:{film_id:id,snapshot:film.state.snapshot,cut_id:film.state.cut_id,destinations:film.film.data.uses,simulation:String(fd.get('simulation'))}});close();location.hash='#/approvals';await refresh();});return;}
 if(action==='handoff'){modal('Prepare a manual production handoff',`${select('Routing label','route',['Greg','Gemini/ORACLE','Claude/Cowork','Hermes'])}<p class="note">This prepares a copy-ready package. It does not deliver, schedule, render, or launch a paid job.</p>`,'Prepare package locally',async fd=>{await api('/films/'+id+'/handoffs',{route:String(fd.get('route'))});close();await refresh();toast('Handoff prepared; no delivery occurred.');});return;}
 if(action==='show-handoff'){const r:Row=film.records.find((v:Row)=>v.id===id);modal('Manual handoff · '+r.data.route,`<p class="notice">Prepared, not delivered. No paid jobs.</p><div class="pre">${esc(r.data.body)}</div>`);return;}
 if(action==='export'){const r=await fetch('/api/films/'+id+'/export/'+el.dataset.format);if(!r.ok){const e=await r.json();throw new Error(e.error)}download(await r.text(),'arcs-production.'+el.dataset.format,r.headers.get('content-type')||'text/plain');toast('Permission-checked export prepared.');return;}
 if(action==='briefing'){await briefing();return;}
 if(action==='meeting'){modal('Import authorized meeting notes',`<div class="notice">Only synthetic notes in this demonstration. Imported notes remain private. Extracted tasks are proposals, never automatically accepted assignments.</div>${field('Document title','title','Synthetic leadership handover notes')}${field('Authorization and restriction reference','authorization','Demo-only internal authorization')}${field('Notes','notes','Propose an accessibility planning task and review current chapter policies.','textarea')}`,'Save restricted notes',async fd=>{await api('/records',{kind:'source',data:{title:String(fd.get('title')),publisher:'Authorized synthetic import',url:null,chapter_scope:'LA',scope_evidence:'Human-provided scope; authorization: '+String(fd.get('authorization')),publication_date:null,retrieved_at:null,period:'synthetic internal notes',content_hash:null,summary:String(fd.get('notes')),retrieval_state:'synthetic',classification:'restricted',location:'Manual notes'}});close();await refresh();toast('Restricted notes saved. Select them explicitly in Agent Workbench to propose tasks.');});return;}
}
document.addEventListener('click',event=>{const target=(event.target as Element).closest<HTMLElement>('[data-action]');if(!target)return;event.preventDefault();void act(target.dataset.action!,target).catch(e=>{const err=document.querySelector('#form-error');if(err&&$<HTMLDialogElement>('#modal').open){err.innerHTML=`<div class="error" role="alert">${esc(e.message)}</div>`;}else toast(e.message);});});
document.addEventListener('submit',event=>{const form=event.target as HTMLFormElement;if(form.id==='modal-form'&&onSubmit){event.preventDefault();const submit=form.querySelector<HTMLButtonElement>('button[type="submit"]')!;submit.disabled=true;const handler=onSubmit;void handler(new FormData(form)).catch(e=>{$('#form-error').innerHTML=`<div class="error" role="alert">${esc(e.message)}</div>`;}).finally(()=>submit.disabled=false);}if(form.id==='report-filter'){event.preventDefault();const f=new FormData(form);void api('/reports?year='+encodeURIComponent(String(f.get('year')))+'&start='+f.get('start')+'&end='+f.get('end')).then(v=>{state.metrics=v;render()}).catch(e=>toast(e.message));}});
document.addEventListener('input',event=>{const el=event.target as HTMLInputElement;if(el.id==='global-search'){search=el.value;applySearch();}});
document.addEventListener('change',event=>{const el=event.target as HTMLSelectElement;if(el.id==='source-filter'){sourceFilter=el.value;render();}if(el.id==='film-select'){filmId=el.value;film=null;location.hash='#/studio/'+filmId;void refresh();}if(el.id==='csv-file'){const input=el as unknown as HTMLInputElement;if(input.files?.[0])void input.files[0].text().then(text=>{const ta=document.querySelector<HTMLTextAreaElement>('[name="csv"]');if(ta)ta.value=text;});}});
window.addEventListener('hashchange',()=>{routeHash();if(state){if(page==='studio')void refresh().catch(e=>toast(e.message));else render();}});
async function start(){routeHash();try{meta=await api('/meta');if(meta.user_authenticated){try{await refresh()}catch{login()}}else login()}catch(e){$('#app').innerHTML=`<main class="login"><h1>Workspace unavailable</h1><p>${esc((e as Error).message)}</p></main>`;}}
void start();
